function SectionTitle({title,eyebrow,children}:{title:string;eyebrow?:string;children?:ReactNode}){return <div className="section-heading"><div>{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h2>{title}</h2></div>{children}</div>}
