function Field({players,pitcher,onPlayer,compact=false}:{players:Player[];pitcher?:Player;onPlayer:(p:Player)=>void;compact?:boolean}){const catcher=players.find(p=>p.pos==='C');const inf=players.filter(p=>p.pos==='IF'),out=players.filter(p=>p.pos==='OF');const pts=[{p:out[0],x:21,y:25,pos:'LF'},{p:out[1],x:50,y:15,pos:'CF'},{p:out[2],x:79,y:25,pos:'RF'},{p:inf[0],x:20,y:57,pos:'3B'},{p:inf[1],x:37,y:43,pos:'SS'},{p:inf[2],x:63,y:43,pos:'2B'},{p:inf[3],x:80,y:57,pos:'1B'},{p:pitcher,x:50,y:62,pos:'P'},{p:catcher,x:50,y:88,pos:'C'}];return <div className={`field ${compact?'compact':''}`}><div className="field-topline"><span>DEFENSIVE ALIGNMENT</span><span>홈 / HOME</span></div><svg className="field-lines" viewBox="0 0 500 400" aria-label="수비 배치도" role="img"><path d="M250 360 L35 145 Q250 -35 465 145 Z" fill="#1a382d" stroke="#43624f" strokeWidth="1"/><path d="M250 360 L70 180 M250 360 L430 180" stroke="#597260" strokeWidth="1"/><path d="M250 340 L148 238 L250 136 L352 238 Z" fill="#233c31" stroke="#749078" strokeWidth="1.5"/><path d="M250 340 L158 248 M250 340 L342 248" stroke="#5f7b68" strokeDasharray="4 5"/><path d="M241 144h18v18h-18z M140 230h15v15h-15z M344 230h15v15h-15z" fill="#a5baa4" transform="rotate(45 250 150)" opacity=".35"/><circle cx="250" cy="254" r="24" fill="none" stroke="#526b51"/><path d="M242 345h16v10l-8 6-8-6z" fill="#bdcbbb"/></svg>{pts.map(t=>t.p&&<button title={`${t.pos} ${t.p.name}`} className="field-player" key={t.pos} style={{left:t.x+'%',top:t.y+'%'}} onClick={()=>onPlayer(t.p!)}><span className={t.pos==='P'?'pitcher':''}>{t.pos}</span><strong>{t.p.name}</strong></button>)}<div className="field-bottomline"><span>선수를 선택해 상세 보기</span><Baseball size={17}/></div></div>}
function Dashboard({g,setView,simulate,busy,onPlayer,replay}:{g:GameState;setView:(v:string)=>void;simulate:()=>void;busy:boolean;onPlayer:(p:Player)=>void;replay:(r:Result)=>void}){
 const {getClub,getLeague,standings,nextFixture}=useWorld();const rows=standings(g),own=rows.find(s=>s.club===g.club)!,rank=rows.findIndex(s=>s.club===g.club)+1,fixture=nextFixture(g);const players=g.lineup.map(id=>g.roster.find(p=>p.id===id)!);const pitcher=g.roster.find(p=>p.id===g.starter),top=[...g.roster].sort((a,b)=>overall(b)-overall(a)).slice(0,4);const [selectedNews,setSelectedNews]=useState<string|null>(null);const selected=g.news.find(n=>n.id===selectedNews)||g.news[0];
 return <><div className="metrics"><Metric label="리그 순위" value={<>{rank}<small> / {rows.length}</small></>} sub={`${own.w}승 ${own.l}패 ${own.d}무 · ${(own.w/(own.w+own.l||1)).toFixed(3)}`}/><Metric label="운영 예산" value={money(g.budget)} sub={g.budget<0?'예산 적자':'영입 · 계약 · 운영'}/><Metric label="선수단 컨디션" value={<>{Math.round(g.roster.reduce((s,p)=>s+p.condition,0)/g.roster.length)}<small>%</small></>} sub={`${g.roster.length}명 · ${g.staff.length}명의 코치`}/><Metric label="최근 경기" value={<div className="form">{own.form.length?own.form.map((v,i)=><span className={v} key={i}>{v}</span>):Array.from({length:5},(_,i)=><span key={i}>–</span>)}</div>} sub="최근 5경기"/></div>
 <div className="dashboard-grid"><aside className="briefing-column"><section className="panel inbox-panel"><div className="panel-header"><h2>구단 소식</h2><span>{g.news.length}</span></div><div className="inbox-list">{g.news.slice(0,7).map(n=><button key={n.id} className={`inbox-item ${selected?.id===n.id?'selected':''}`} onClick={()=>setSelectedNews(n.id)}><span className={`news-icon ${n.kind}`}>{n.kind==='match'?<Baseball size={14}/>:n.kind==='transfer'?<Handshake size={14}/>:<ClipboardList size={14}/>}</span><span><small>{n.day+1}일차 · {n.kind==='match'?'경기 보고':n.kind==='transfer'?'계약':n.kind==='training'?'훈련 보고':'구단'}</small><strong>{n.title}</strong></span></button>)}</div>{selected&&<article className="inbox-detail"><span className="label">{selected.day+1}일차 보고</span><h3>{selected.title}</h3><p>{selected.body}</p></article>}</section>
 <section className="panel"><div className="panel-header"><h2>주요 선수</h2><button className="text-button" onClick={()=>setView('squad')}>선수단<ChevronRight size={12}/></button></div><div className="top-players">{top.map(p=><div key={p.id}><PlayerName p={p} onClick={onPlayer}/><Rating value={overall(p)}/></div>)}</div></section></aside>
 <div className="main-column"><section className="panel next-match"><div className="panel-header"><h2>다음 경기</h2><span>{g.phase==='regular'?'정규 시즌':g.phase==='finished'?'시즌 종료':'포스트시즌'}</span></div>{fixture?<><div className="match-meta"><span>{getLeague(getClub(g.club).league).name}</span><span>{g.day+1}일차 · {getClub(fixture[0]).city}</span></div><div className="matchup"><div><Badge club={getClub(fixture[1])} size="large"/><strong>{getClub(fixture[1]).name}</strong><small>원정</small></div><div className="versus"><b>v</b></div><div><Badge club={getClub(fixture[0])} size="large"/><strong>{getClub(fixture[0]).name}</strong><small>홈</small></div></div><div className="match-bottom"><span>선발 <strong>{pitcher?.name}</strong><span className="muted">{Math.round(pitcher?.condition||0)}%</span></span><button className="text-button" disabled={busy} onClick={simulate}>경기 진행<ChevronRight size={14}/></button></div></>:<div className="empty-state"><Trophy size={25}/><h3>{g.phase==='finished'?`${getClub(g.champion).name} 우승`:'예정된 경기가 없습니다'}</h3><p>{g.phase==='finished'?'재계약을 확인한 뒤 다음 시즌을 시작하세요.':'선수단을 정비하거나 다음 날로 진행하세요.'}</p></div>}</section>
 <section className="panel"><div className="panel-header"><h2>전술 · 수비 배치</h2><button className="text-button" onClick={()=>setView('tactics')}>설정<ChevronRight size={13}/></button></div><Field players={players} pitcher={pitcher} onPlayer={onPlayer} compact/><div className="tactic-summary"><Target size={14}/><strong>{tactics.find(t=>t[0]===g.tactic)?.[1]}</strong><span>선발 {players.length}명</span></div></section></div>
 <aside className="right-column"><section className="panel"><div className="panel-header"><h2>리그 순위</h2><button className="text-button" onClick={()=>setView('world')}>전체<ChevronRight size={13}/></button></div><StandingsTable g={g} compact/></section><section className="panel"><div className="panel-header"><h2>최근 결과</h2><button className="text-button" onClick={()=>setView('schedule')}>일정<ChevronRight size={13}/></button></div>{g.history.length?<div className="compact-results">{g.history.slice(0,5).map(r=><button key={r.id} onClick={()=>replay(r)}><small>{r.day+1}일차</small><span>{getClub(r.away).short}</span><strong>{r.awayScore}–{r.homeScore}</strong><span>{getClub(r.home).short}</span><ChevronRight size={12}/></button>)}</div>:<div className="empty-state"><p>아직 치른 경기가 없습니다.</p></div>}</section><section className="panel club-checklist"><div className="panel-header"><h2>계약 현황</h2></div><button onClick={()=>setView('agents')}><span>진행 중인 협상</span><b>{g.deals.length}</b><ChevronRight size={13}/></button><button onClick={()=>setView('squad')}><span>계약 잔여 1년</span><b>{g.roster.filter(p=>p.years===1).length}명</b><ChevronRight size={13}/></button><button onClick={()=>setView('staff')}><span>코칭 스태프</span><b>{g.staff.length}명</b><ChevronRight size={13}/></button></section></aside></div></>;
}
function StandingsTable({g,league,compact=false}:{g:GameState;league?:string;compact?:boolean}){const {getClub,standings}=useWorld();const rows=standings(g,league);const ownIndex=rows.findIndex(s=>s.club===g.club);const show=compact?(ownIndex>=8?[...rows.slice(0,7),rows[ownIndex]]:rows.slice(0,8)):rows;return <Table className="data-table standings-table"><TableHeader><TableRow><TableHead>#</TableHead><TableHead>구단</TableHead><TableHead>승</TableHead><TableHead>패</TableHead>{!compact&&<TableHead>무</TableHead>}<TableHead>승률</TableHead>{!compact&&<><TableHead>승차</TableHead><TableHead>득실</TableHead><TableHead>최근 5경기</TableHead></>}</TableRow></TableHeader><TableBody>{show.map((s,i)=><TableRow key={s.club} className={s.club===g.club?'my-team':''}><TableCell>{rows.indexOf(s)+1}</TableCell><TableCell><span className="table-club"><Badge club={getClub(s.club)} size="tiny"/>{compact?getClub(s.club).short:getClub(s.club).name}{s.club===g.club&&<span className="you">MY</span>}</span></TableCell><TableCell>{s.w}</TableCell><TableCell>{s.l}</TableCell>{!compact&&<TableCell>{s.d}</TableCell>}<TableCell>{s.w+s.l?(s.w/(s.w+s.l)).toFixed(3):'.000'}</TableCell>{!compact&&<><TableCell>{i===0?'–':((rows[0].w-s.w+s.l-rows[0].l)/2).toFixed(1)}</TableCell><TableCell>{s.rf-s.ra>0?'+':''}{s.rf-s.ra}</TableCell><TableCell><span className="form">{s.form.map((v,j)=><span key={j} className={v}>{v}</span>)}</span></TableCell></>}</TableRow>)}</TableBody></Table>}
function PlayerTable({players,onPlayer,kind='squad',g}:{players:Player[];onPlayer:(p:Player)=>void;kind?:string;g:GameState}){const {getClub}=useWorld();return <Table className="data-table player-table"><TableHeader><TableRow><TableHead>선수</TableHead><TableHead>구분</TableHead><TableHead>나이</TableHead><TableHead>OVR</TableHead><TableHead>잠재력</TableHead>{kind==='market'?<><TableHead>소속 구단</TableHead><TableHead>예상 이적료</TableHead><TableHead>연봉</TableHead></>:<><TableHead>컨디션</TableHead><TableHead>경기</TableHead><TableHead>AVG / ERA</TableHead><TableHead>HR / 승</TableHead><TableHead>연봉</TableHead></>}<TableHead/></TableRow></TableHeader><TableBody>{players.map(p=><TableRow key={p.id}><TableCell><PlayerName p={p} onClick={onPlayer}/></TableCell><TableCell>{positions[p.pos]}</TableCell><TableCell>{p.age}</TableCell><TableCell><Rating value={overall(p)}/></TableCell><TableCell><span className="potential">{kind==='market'?`${Math.max(overall(p),p.potential-Math.round((100-coachSkill(g,'스카우트'))/8))}–${Math.min(99,p.potential+Math.round((100-coachSkill(g,'스카우트'))/8))}`:Math.round(p.potential)}</span></TableCell>{kind==='market'?<><TableCell><span className="muted">{p.club==='fa'?'FA · 자유계약':getClub(p.club)?.name||'이적 선수'}</span></TableCell><TableCell>{money(askPrice(p))}</TableCell><TableCell>{money(p.salary)}</TableCell></>:<><TableCell><div className="condition"><Progress value={p.condition}/><span>{Math.round(p.condition)}%</span></div></TableCell><TableCell>{p.stats.g}</TableCell><TableCell>{p.pos==='P'?p.stats.outs?(p.stats.er*27/p.stats.outs).toFixed(2):'–':p.stats.ab?(p.stats.h/p.stats.ab).toFixed(3):'–'}</TableCell><TableCell>{p.pos==='P'?p.stats.wins:p.stats.hr}</TableCell><TableCell>{money(p.salary)}<small className="block muted">{p.years}년 남음</small></TableCell></>}<TableCell><button className="icon-button" aria-label={`${p.name} 상세 보기`} onClick={()=>onPlayer(p)}><ArrowUpRight size={17}/></button></TableCell></TableRow>)}</TableBody></Table>}
function Squad({g,onPlayer}:{g:GameState;onPlayer:(p:Player)=>void}){const [filter,setFilter]=useState('all'),[query,setQuery]=useState(''),[sort,setSort]=useState('rating');const list=g.roster.filter(p=>(filter==='all'||p.pos===filter||filter==='young'&&p.age<=23)&&p.name.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='age'?a.age-b.age:sort==='salary'?b.salary-a.salary:overall(b)-overall(a));return <section className="panel"><div className="toolbar"><Tabs value={filter} onValueChange={setFilter}><TabsList variant="line">{[['all','전체 선수'],['P','투수'],['C','포수'],['IF','내야수'],['OF','외야수'],['young','유망주']].map(t=><TabsTrigger value={t[0]} key={t[0]}>{t[1]}</TabsTrigger>)}</TabsList></Tabs><div className="toolbar-controls"><SearchBox value={query} onChange={setQuery}/><Choice label="선수 정렬" value={sort} onChange={setSort} items={[{value:'rating',label:'능력치 순'},{value:'age',label:'어린 선수 순'},{value:'salary',label:'연봉 순'}]}/></div></div><PlayerTable players={list} onPlayer={onPlayer} g={g}/>{!list.length&&<Empty text="조건에 맞는 선수가 없습니다."/>}<div className="panel-foot">{list.length}명 · 실명 {list.filter(p=>p.real).length}명 / 가상 {list.filter(p=>!p.real).length}명<span>능력치·연봉은 게임 설정 · 나이는 시즌 연도 기준</span></div></section>}
function SearchBox({value,onChange,placeholder='선수 검색'}:{value:string;onChange:(s:string)=>void;placeholder?:string}){return <label className="search-box"><Search size={16}/><input aria-label={placeholder} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/>{value&&<button aria-label="검색어 지우기" onClick={()=>onChange('')}><X size={14}/></button>}</label>}
function Empty({text}:{text:string}){return <div className="empty-state"><Search size={27}/><p>{text}</p></div>}
function Tactics({g,act,busy,onPlayer}:{g:GameState;act:Act;busy:boolean;onPlayer:(p:Player)=>void}){const players=g.lineup.map(id=>g.roster.find(p=>p.id===id)!);const pitcher=g.roster.find(p=>p.id===g.starter);function swap(i:number,j:number){if(j<0||j>8)return;const ids=[...g.lineup];[ids[i],ids[j]]=[ids[j],ids[i]];void act({type:'lineup',ids});}return <div className="tactics-layout"><div><section className="panel"><div className="panel-header"><h2>수비 배치</h2><span className="pill">DH 적용</span></div><Field players={players} pitcher={pitcher} onPlayer={onPlayer}/><div className="panel-content"><label className="label">다음 경기 선발 투수</label><Choice value={g.starter} label="선발 투수" onChange={id=>{if(!busy)void act({type:'starter',id})}} items={g.roster.filter(p=>p.pos==='P').sort((a,b)=>overall(b)-overall(a)).map(p=>({value:p.id,label:`${p.name} · OVR ${overall(p)} · 컨디션 ${Math.round(p.condition)}%`}))}/><p className="tiny">경기 후에는 컨디션을 고려해 선발 로테이션을 자동 갱신합니다.</p></div></section><section className="panel training-block"><div className="panel-header"><h2>공격 전술</h2><Target size={18}/></div><div className="tactic-choices">{tactics.map(t=><button key={t[0]} disabled={busy} className={g.tactic===t[0]?'selected':''} onClick={()=>act({type:'tactic',value:t[0]})}><span className="radio-mark">{g.tactic===t[0]&&<Check size={12}/>}</span><span><strong>{t[1]}</strong><small>{t[2]}</small></span></button>)}</div></section></div><section className="panel"><div className="panel-header"><h2>선발 타순</h2><button className="text-button" disabled={busy} onClick={()=>act({type:'auto'})}><Sparkles size={15}/> 코치 추천</button></div><div className="lineup-list">{players.map((p,i)=><div className="lineup-item" key={p.id}><span className="batting-order">{i+1}</span><div className="lineup-player"><Choice value={p.id} label={`${i+1}번 타자`} onChange={id=>{if(busy)return;const ids=[...g.lineup],old=ids.indexOf(id);if(old>=0)[ids[i],ids[old]]=[ids[old],ids[i]];else ids[i]=id;void act({type:'lineup',ids})}} items={g.roster.filter(v=>v.pos!=='P').map(v=>({value:v.id,label:`${v.name} · ${positions[v.pos]}`}))}/><span className="muted">컨택 {Math.round(p.contact)} · 파워 {Math.round(p.power)} · 주력 {Math.round(p.speed)}</span></div><Rating value={overall(p)}/><div className="order-buttons"><button disabled={busy||i===0} aria-label={`${p.name} 타순 올리기`} onClick={()=>swap(i,i-1)}><ArrowUp size={14}/></button><button disabled={busy||i===8} aria-label={`${p.name} 타순 내리기`} onClick={()=>swap(i,i+1)}><ArrowDown size={14}/></button></div></div>)}</div><div className="panel-content tiny">포수 1명 · 내야수 4명 · 외야수 3명 · 지명타자 1명. 같은 선수를 선택하면 타순이 서로 바뀝니다. 세부 수비 위치는 게임 내 자동 배치입니다.</div></section></div>}
function Schedule({g,replay}:{g:GameState;replay:(r:Result)=>void}){const {getClub,pairings}=useWorld();const upcoming=Array.from({length:Math.min(14,Math.max(0,g.rounds-g.day))},(_,i)=>({day:g.day+i,pair:pairings(getClub(g.club).league,g.day+i).find(p=>p.includes(g.club))}));return <><div className="two-column"><section className="panel"><div className="panel-header"><h2>다가오는 일정</h2><span className="pill">{g.mode==='short'?'단축 시즌':'정규 길이'}</span></div>{g.phase==='regular'?upcoming.map(f=><div className="fixture-row" key={f.day}><span className="day-chip"><small>DAY</small>{f.day+1}</span>{f.pair?<><Badge club={getClub(f.pair.find(p=>p!==g.club)!)} size="small"/><strong>{getClub(f.pair.find(p=>p!==g.club)!).name}</strong><span className="pill">{f.pair[0]===g.club?'HOME':'AWAY'}</span></>:<strong>휴식일</strong>}</div>):<div className="panel-content"><h3>{g.phase==='finished'?'시즌 종료':'포스트시즌'}</h3>{g.series.map((s,i)=><div className="series-row" key={i}>{getClub(s.a).name}<strong>{s.aw} – {s.bw}</strong>{getClub(s.b).name}</div>)}</div>}</section><section className="panel"><div className="panel-header"><h2>경기 기록</h2><span>{g.history.length}경기</span></div>{g.history.length?g.history.map(r=><button className="result-row" key={r.id} onClick={()=>replay(r)}><span className="muted">DAY {r.day+1}</span><span>{getClub(r.away).short}</span><strong>{r.awayScore} : {r.homeScore}</strong><span>{getClub(r.home).short}</span><Play size={14}/></button>):<Empty text="첫 경기를 진행하면 기록이 쌓입니다."/>}</section></div></>}
function World({g,onPlayer}:{g:GameState;onPlayer:(p:Player)=>void}){const {clubs,leagues,getClub,getLeague,rosterFor}=useWorld();const [lid,setLid]=useState(getClub(g.club).league),[team,setTeam]=useState('');const l=getLeague(lid);const roster=team&&team!=='none'?rosterFor(g,team):[];return <><div className="world-strip">{leagues.map(v=><button key={v.id} className={lid===v.id?'selected':''} onClick={()=>{setLid(v.id);setTeam('')}}><span>{v.flag}</span><strong>{v.name}</strong><small>{v.country}</small></button>)}</div><section className="panel"><div className="panel-header"><h2>{l.flag} {l.label}</h2><a href={l.source} target="_blank" rel="noreferrer" className="text-button">공식 리그 <ExternalLink size={14}/></a></div><StandingsTable g={g} league={lid}/><div className="panel-foot">{l.country} · {l.season}<span>게임 내 순위 · 현실 리그 성적과 별도</span></div></section><section className="panel club-inspector"><div className="panel-header"><h2>세계 구단 선수단</h2><Choice label="구단 선수단 보기" value={team||'none'} onChange={setTeam} items={[{value:'none',label:'구단을 선택하세요'},...clubs.filter(c=>c.league===lid).map(c=>({value:c.id,label:c.name}))]}/></div>{team&&team!=='none'?<PlayerTable players={[...roster].sort((a,b)=>overall(b)-overall(a))} onPlayer={onPlayer} kind="market" g={g}/>:<Empty text="구단을 선택하면 실명 선수와 유망주를 살펴볼 수 있습니다."/>}</section></>}
function Market({g,onPlayer}:{g:GameState;onPlayer:(p:Player)=>void}){const {leagues,getClub,marketPlayers}=useWorld();const [query,setQuery]=useState(''),[lid,setLid]=useState('all'),[pos,setPos]=useState('all'),[kind,setKind]=useState('all'),[page,setPage]=useState(0),[sort,setSort]=useState('rating');const market=useMemo(()=>marketPlayers(g),[g.club,g.year,g.ownership,g.roster]);const list=useMemo(()=>market.filter(p=>(lid==='all'||lid==='fa'&&p.club==='fa'||getClub(p.club)?.league===lid)&&(pos==='all'||p.pos===pos)&&(kind==='all'||kind==='real'&&p.real||kind==='generated'&&!p.real)&&`${p.name} ${p.original}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='value'?askPrice(a)-askPrice(b):sort==='potential'?b.potential-a.potential:overall(b)-overall(a)),[market,lid,pos,kind,query,sort]);const pages=Math.max(1,Math.ceil(list.length/25));const current=Math.min(page,pages-1);return <><div className="market-notice"><Globe2 size={24}/><div><strong>국경 너머, 다음 프랜차이즈 스타.</strong><p>{market.filter(p=>p.real).length.toLocaleString()}명의 실명 선수와 {market.filter(p=>!p.real).length.toLocaleString()}명의 가상 선수 · 스카우트 능력 {coachSkill(g,'스카우트')}</p></div><div><span className="label">사용 가능한 예산</span><strong className="accent">{money(g.budget)}</strong></div></div><section className="panel"><div className="market-filters"><SearchBox value={query} onChange={s=>{setQuery(s);setPage(0)}} placeholder="선수 이름 검색 · 오타니, 저지, 김도영"/><Choice label="리그 필터" value={lid} onChange={v=>{setLid(v);setPage(0)}} items={[{value:'all',label:'전 세계 리그'},{value:'fa',label:'FA · 자유계약'},...leagues.map(l=>({value:l.id,label:`${l.flag} ${l.name}`}))]}/><Choice label="포지션 필터" value={pos} onChange={v=>{setPos(v);setPage(0)}} items={[{value:'all',label:'모든 포지션'},...Object.entries(positions).map(([value,label])=>({value,label}))]}/><Choice label="선수 유형" value={kind} onChange={v=>{setKind(v);setPage(0)}} items={[{value:'all',label:'실명 + 가상'},{value:'real',label:'실명 선수'},{value:'generated',label:'가상 선수'}]}/><Choice label="시장 정렬" value={sort} onChange={setSort} items={[{value:'rating',label:'능력치 높은 순'},{value:'potential',label:'잠재력 높은 순'},{value:'value',label:'이적료 낮은 순'}]}/></div><PlayerTable players={list.slice(current*25,(current+1)*25)} g={g} onPlayer={onPlayer} kind="market"/>{!list.length&&<Empty text="검색 조건에 맞는 선수가 없습니다."/>}<div className="pagination"><span>{list.length.toLocaleString()}명 중 {list.length?current*25+1:0}–{Math.min((current+1)*25,list.length)}</span><div><button aria-label="이전 페이지" disabled={current===0} onClick={()=>setPage(current-1)}><ChevronLeft size={18}/></button><span>{current+1} / {pages}</span><button aria-label="다음 페이지" disabled={current>=pages-1} onClick={()=>setPage(current+1)}><ChevronRight size={18}/></button></div></div></section></>}
function Agents({g,act,busy,onPlayer}:{g:GameState;act:Act;busy:boolean;onPlayer:(p:Player)=>void}){const {agentFor}=useWorld();return <><div className="agent-intro"><Handshake size={28}/><div><h3>계약 테이블</h3><p>수락된 조건이나 역제안에 최종 서명하면 이적료·계약금·수수료가 지출됩니다. 제안은 14일간 유효합니다.</p></div></div>{g.deals.length?<div className="deal-grid">{g.deals.map(d=>{const a=agentFor(d.player);return <section className="panel deal-card" key={d.id}><div className="panel-header"><span className={`pill ${d.status==='accepted'?'lime':d.status==='counter'?'amber':''}`}>{d.status==='accepted'?'계약 합의':d.status==='counter'?'역제안 도착':'제안 거절'}</span><span className="muted">{d.type==='renew'?'재계약':'신규 영입'}</span></div><div className="panel-content"><div className="deal-player"><PlayerName p={d.player} onClick={onPlayer}/><Rating value={overall(d.player)}/></div><p className="agent-message">“{d.message}”</p><div className="agent-signature"><span className="manager-avatar"><UserRound size={19}/></span><span><strong>{a.name}</strong><small>{a.agency} · 수수료 {(a.fee*100).toFixed(0)}%</small></span></div><div className="deal-terms"><div><small>연봉</small><strong>{money(d.salary)}</strong></div><div><small>계약 기간</small><strong>{d.years}년</strong></div><div><small>이적료</small><strong>{money(d.fee)}</strong></div></div><div className="cost-line"><span>지금 지출 · 계약금 15% + 수수료 + 이적료</span><strong>{money(d.fee+d.agentFee+d.salary*.15)}</strong></div><button className="button primary full-width" disabled={busy||d.status==='rejected'||g.day-d.day>14} onClick={async()=>{if(await act({type:'sign',id:d.id}))toast.success('계약에 서명했습니다. 선수단에서 확인하세요.')}}>{g.day-d.day>14?'제안 만료':d.status==='counter'?'역제안 수락 · 계약 체결':'최종 서명'}<Check size={16}/></button></div></section>})}</div>:<section className="panel"><div className="empty-state"><Handshake size={42}/><h3>진행 중인 협상이 없습니다</h3><p>영입 · 이적에서 선수를 선택해 에이전트에게 제안하세요.<br/>소속 선수의 상세 화면에서는 재계약을 제안할 수 있습니다.</p></div></section>}</>}
function Staff({g,act,busy}:{g:GameState;act:Act;busy:boolean}){const {coachPool}=useWorld();const [role,setRole]=useState<string|null>(null);return <><div className="staff-grid">{coachRoles.map(r=>{const c=g.staff.find(c=>c.role===r)!;return <section className="panel coach-card" key={r}><div className="coach-role"><span>{r} 코치</span><GraduationCap size={18}/></div><div className="coach-portrait"><UserRound size={45}/><span className="gen-tag">가상 코치</span></div><h3>{c.name}</h3><p>{c.style}</p><div className="coach-score"><Rating value={c.skill}/><span>코칭 능력</span></div><div className="cost-line"><span>연봉</span><strong>{money(c.salary)}</strong></div><button className="button secondary full-width compact" onClick={()=>setRole(r)}>코치 후보 보기 <ChevronRight size={15}/></button></section>})}</div><section className="panel"><div className="panel-header"><h2>팀 훈련 계획</h2><span className="pill">경기 진행 시 반영</span></div><div className="training-options">{trainings.map(t=><button key={t[0]} className={g.training===t[0]?'selected':''} disabled={busy} onClick={()=>act({type:'training',value:t[0]})}><div><span className="radio-mark">{g.training===t[0]&&<Check size={12}/>}</span><strong>{t[1]}</strong></div><p>{t[2]}</p></button>)}</div><div className="panel-content muted">코칭 능력이 높을수록 해당 훈련의 성장 폭이 커집니다. 체력 코치는 매일 회복량을, 스카우트는 잠재력 예상 범위의 정확도를 높입니다. 31세 미만 선수에게 성장 기회가 주어집니다.</div></section><Dialog open={!!role} onOpenChange={o=>{if(!o)setRole(null)}}><DialogContent className="game-dialog"><DialogHeader><DialogTitle>{role} 코치 후보</DialogTitle><DialogDescription>선임하면 기존 담당 코치가 교체됩니다. 계약금은 연봉의 50%입니다.</DialogDescription></DialogHeader><div className="coach-candidates">{coachPool(g.year).filter(c=>c.role===role).map(c=><div key={c.id}><span className="manager-avatar"><UserRound size={22}/></span><div><strong>{c.name}</strong><small>{c.style} · 연봉 {money(c.salary)}</small></div><Rating value={c.skill}/><button className="button primary compact" disabled={busy||g.staff.some(s=>s.id===c.id)} onClick={async()=>{if(await act({type:'coach',id:c.id})){setRole(null);toast.success(`${c.name} 코치를 선임했습니다.`)}}}>{g.staff.some(s=>s.id===c.id)?'선임됨':`선임 ${money(c.salary*.5)}`}</button></div>)}</div></DialogContent></Dialog></>}
function Finance({g,ledger}:{g:GameState;ledger:FinanceEntry[]}){const wages=g.roster.reduce((s,p)=>s+p.salary,0),coaches=g.staff.reduce((s,c)=>s+c.salary,0);return <><div className="metrics"><Metric label="현재 잔액" value={money(g.budget)} sub="영입 및 운영 예산" icon={<Wallet size={18}/>}/><Metric label="이번 시즌 수입" value={money(g.income)} sub="경기 수익 · 매각 · 상금" icon={<ArrowUpRight size={18}/>}/><Metric label="이번 시즌 지출" value={money(g.expenses)} sub="급여 · 계약금 · 이적료 · 수수료" icon={<DollarSign size={18}/>}/><Metric label="총 연간 급여" value={money(wages+coaches)} sub="선수와 코치의 연봉 합계" icon={<Users size={18}/>}/></div><section className="panel ledger-panel"><div className="panel-header"><h2>거래 내역</h2><span>최근 60건 · 자동 기록</span></div><Table><TableHeader><TableRow><TableHead>시즌 · 일차</TableHead><TableHead>내용</TableHead><TableHead>변동</TableHead><TableHead>잔액</TableHead></TableRow></TableHeader><TableBody>{ledger.map(e=><TableRow key={e.id}><TableCell>{e.year} · {e.day}일</TableCell><TableCell>{{start:'구단 운영 자금',advance:'경기 수입 · 급여',sign:'선수 계약',sell:'선수 매각',coach:'코치 계약',nextSeason:'새 시즌 지원금'}[e.kind]||e.kind}</TableCell><TableCell className={e.amount>0?'accent':''}>{e.amount>0?'+':'−'}{money(Math.abs(e.amount))}</TableCell><TableCell>{money(e.balance)}</TableCell></TableRow>)}</TableBody></Table>{!ledger.length&&<Empty text="아직 거래 내역이 없습니다."/>}</section><div className="two-column"><section className="panel"><div className="panel-header"><h2>연봉 상위 선수</h2><span>게임 내 계약</span></div><div className="salary-list">{[...g.roster].sort((a,b)=>b.salary-a.salary).slice(0,10).map(p=><div key={p.id}><strong>{p.name}</strong><span className="muted">{p.years}년</span><div><Progress value={p.salary/Math.max(...g.roster.map(p=>p.salary))*100}/></div><b>{money(p.salary)}</b></div>)}</div></section><div><section className="panel"><div className="panel-header"><h2>운영 구조</h2></div><div className="panel-content finance-details"><div><span>선수 연봉 합계</span><strong>{money(wages)}</strong></div><div><span>코치 연봉 합계</span><strong>{money(coaches)}</strong></div><div><span>하루 급여 지출</span><strong>{money((wages+coaches)/g.rounds)}</strong></div><p>통화는 비교를 위해 USD로 통일합니다. M은 백만 달러, K는 천 달러입니다. 실제 선수 연봉과는 다릅니다.</p><p>홈 경기는 원정 경기보다 수입이 높고, 승리하면 보너스 수입이 발생합니다. 새 시즌에는 구단 지원금이 지급됩니다.</p></div></section><section className="panel training-block"><div className="panel-header"><h2>커리어 기록</h2><Trophy size={18}/></div>{g.past.length?<div className="panel-content">{g.past.map(y=><div className="career-record" key={y.year}><strong>{y.year}</strong><span>{y.rank}위 · {y.w}승 {y.l}패</span>{y.champion===g.club&&<span className="pill lime">우승</span>}</div>)}</div>:<Empty text="첫 시즌을 마치면 커리어 기록이 남습니다."/>}</section></div></div></>}
function PlayerModal({p,g,close,act,busy}:{p:Player|null;g:GameState;close:()=>void;act:Act;busy:boolean}){const {getClub,agentFor}=useWorld();const [salary,setSalary]=useState(''),[years,setYears]=useState('3'),[tab,setTab]=useState('profile'),[sell,setSell]=useState(false);useEffect(()=>{if(p){setSalary(String(Math.round(p.salary*1.1)));setYears('3');setTab('profile');setSell(false)}},[p?.id]);if(!p)return null;const own=g.roster.some(x=>x.id===p.id);const agent=agentFor(p);const attrs=p.pos==='P'?[['구위',p.stuff],['제구',p.control],['수비',p.field],['잠재력',p.potential]]:[['컨택',p.contact],['파워',p.power],['주력',p.speed],['수비',p.field]];return <><Dialog open={!!p} onOpenChange={o=>{if(!o)close()}}><DialogContent className="game-dialog player-dialog"><DialogHeader><DialogTitle className="sr-only">{p.name} 선수 상세</DialogTitle><DialogDescription className="sr-only">선수 능력, 계약 조건, 에이전트 협상</DialogDescription></DialogHeader><div className="profile-header"><span className={`profile-number ${p.real?'':'generated'}`}>{p.number}</span><div><span className={p.real?'real-tag':'gen-tag'}>{p.real?'실명 선수':'가상 선수'}</span><h2>{p.name}</h2><p>{positions[p.pos]} · {p.age}세 · {p.club==='fa'?'FA · 자유계약':getClub(p.club)?.name}</p></div><Rating value={overall(p)}/></div><Tabs value={tab} onValueChange={setTab}><TabsList className="profile-tabs" variant="line"><TabsTrigger value="profile">선수 프로필</TabsTrigger><TabsTrigger value="contract">{own?'재계약 · 이적':'계약 협상'}</TabsTrigger></TabsList><TabsContent value="profile"><div className="attribute-grid">{attrs.map(([label,value])=><div key={String(label)}><span>{label}</span><strong>{Math.round(Number(value))}</strong><Progress value={Number(value)}/></div>)}</div><div className="profile-facts"><div><small>연봉</small><strong>{money(p.salary)}</strong></div><div><small>계약 잔여</small><strong>{p.years}년</strong></div><div><small>컨디션</small><strong>{Math.round(p.condition)}%</strong></div></div><div className="profile-season"><strong>게임 내 시즌 기록</strong><span>{p.pos==='P'?`${p.stats.g}경기 · ${p.stats.wins}승 · ERA ${p.stats.outs?(p.stats.er*27/p.stats.outs).toFixed(2):'–'}`:`${p.stats.g}경기 · ${p.stats.h}안타 · ${p.stats.hr}홈런 · ${p.stats.rbi}타점`}</span></div><p className="tiny">능력치·연봉·잠재력은 게임용 설정입니다. 실명 선수 나이는 시즌 연도와 출생연도의 차이입니다.{p.real&&p.source&&<> <a href={p.source} target="_blank" rel="noreferrer">선수 명단 출처 ↗</a></>}</p><button className="button primary full-width" onClick={()=>setTab('contract')}><Handshake size={17}/>{own?'계약 관리':'에이전트에게 연락'}</button></TabsContent><TabsContent value="contract"><div className="agent-contact"><span className="manager-avatar"><UserRound size={22}/></span><div><strong>{agent.name} <span className="gen-tag">가상 에이전트</span></strong><small>{agent.agency} · {agent.priority}</small></div><span className="pill">수수료 {(agent.fee*100).toFixed(0)}%</span></div><p className="agent-message">“{p.name} 선수에게 어떤 조건을 제안하시겠습니까?”</p><div className="contract-inputs"><label>제안 연봉 (단위: $10K)<input type="number" min="1" max="100000" step="1" value={salary} onChange={e=>setSalary(e.target.value)}/><small>{money(Number(salary)||0)} / 시즌</small></label><label>계약 기간<Choice label="계약 기간" value={years} onChange={setYears} items={[1,2,3,4,5].map(n=>({value:String(n),label:`${n}년`}))}/></label></div><div className="contract-costs"><div><span>구단 이적료</span><strong>{money(own?0:askPrice(p))}</strong></div><div><span>예상 에이전트 수수료</span><strong>{money((Number(salary)||0)*agent.fee)}</strong></div><div><span>계약금 · 첫해 연봉의 15%</span><strong>{money((Number(salary)||0)*.15)}</strong></div><div><span>구단 예산</span><strong>{money(g.budget)}</strong></div></div><button className="button primary full-width" disabled={busy||!(Number(salary)>0)} onClick={async()=>{const next=await act({type:'negotiate',id:p.id,salary:Number(salary),years:Number(years),renew:own});if(next){const deal=next.deals[0];toast(deal.message);close();}}}>조건 제안하기 <ArrowRight size={16}/></button><p className="tiny">협상 결과는 에이전트 메뉴에서 확인하세요. 구단 수준보다 높은 능력의 선수는 더 높은 연봉을 요구합니다.</p>{own&&<button className="button danger full-width" disabled={busy} onClick={()=>setSell(true)}>이적 제안 수락 · 매각 {money(askPrice(p)*.7)}</button>}</TabsContent></Tabs></DialogContent></Dialog><AlertDialog open={sell} onOpenChange={setSell}><AlertDialogContent className="confirm-dialog"><AlertDialogHeader><AlertDialogTitle>{p.name} 선수를 이적시킬까요?</AlertDialogTitle><AlertDialogDescription>다른 구단으로 이적하고 {money(Math.round(askPrice(p)*.7))}을 받습니다. 타순은 다시 자동 편성됩니다.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>취소</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={async()=>{if(await act({type:'sell',id:p.id})){close();toast.success('이적이 완료됐습니다.')}}}>매각 확정</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>}
function Replay({result,close}:{result:Result|null;close:()=>void}){const {getClub}=useWorld();const [inning,setInning]=useState(1);useEffect(()=>{setInning(1)},[result?.id]);if(!result)return null;const r=result,max=Math.max(r.innings[0]?.length||9,r.innings[1]?.length||9),done=inning>=max;const sum=(side:number)=>r.innings[side].slice(0,inning).reduce<number>((s,n)=>s+(n||0),0);return <Dialog open={!!result} onOpenChange={o=>{if(!o)close()}}><DialogContent className="game-dialog replay-dialog"><DialogHeader><DialogTitle>경기 리플레이</DialogTitle><DialogDescription>시즌 {r.day+1}일차 · {r.post?'포스트시즌':'정규 시즌'} · 저장된 경기 결과</DialogDescription></DialogHeader><div className="replay-score"><div><Badge club={getClub(r.away)} size="large"/><strong>{getClub(r.away).name}</strong></div><div><span className="pill lime">{done?'FINAL':`${inning} INNING`}</span><strong>{sum(0)}<i>:</i>{sum(1)}</strong></div><div><Badge club={getClub(r.home)} size="large"/><strong>{getClub(r.home).name}</strong></div></div><Table className="scoreboard"><TableHeader><TableRow><TableHead>TEAM</TableHead>{Array.from({length:max},(_,i)=><TableHead key={i}>{i+1}</TableHead>)}<TableHead>R</TableHead><TableHead>H</TableHead><TableHead>E</TableHead></TableRow></TableHeader><TableBody>{[0,1].map(s=><TableRow key={s}><TableCell>{getClub(s?r.home:r.away).short}</TableCell>{Array.from({length:max},(_,i)=><TableCell key={i} className={i===inning-1?'current-inning':''}>{i>=inning?'·':r.innings[s][i]===null?'X':r.innings[s][i]??'–'}</TableCell>)}<TableCell className="accent">{sum(s)}</TableCell><TableCell>{done?r.hits[s]:'–'}</TableCell><TableCell>{done?r.errors[s]:'–'}</TableCell></TableRow>)}</TableBody></Table><div className="play-log">{r.log.filter(e=>e.inning===inning).map((e,i)=><div key={i}><span className="inning-marker">{e.inning}회 {e.half?'말':'초'}</span><span>{e.text}</span><b>{e.score[0]} : {e.score[1]}</b></div>)}{done&&<div className="mvp"><Trophy size={18}/> 경기 MVP <strong>{r.mvp}</strong></div>}</div><div className="replay-controls"><button className="button secondary compact" disabled={inning===1} onClick={()=>setInning(inning-1)}><ChevronLeft size={16}/>이전 이닝</button><button className="text-button" disabled={done} onClick={()=>setInning(max)}>최종 결과</button><button className="button primary compact" onClick={()=>done?close():setInning(inning+1)}>{done?'더그아웃으로':'다음 이닝'}<ChevronRight size={16}/></button></div></DialogContent></Dialog>}
function Help({open,close}:{open:boolean;close:()=>void}){const {rosterNote}=useWorld();return <Dialog open={open} onOpenChange={o=>{if(!o)close()}}><DialogContent className="game-dialog help-dialog"><DialogHeader><DialogTitle>DUGOUT 플레이 가이드</DialogTitle><DialogDescription>구단 선택부터 챔피언십까지</DialogDescription></DialogHeader><div className="help-copy"><h3>시즌 진행</h3><p>타순과 선발, 공격 전술을 정한 뒤 경기를 진행하세요. 선수 능력과 컨디션, 코칭이 경기와 성장에 반영됩니다. 경기 결과는 리플레이에서 이닝별로 확인할 수 있습니다.</p><h3>영입 · 이적 · 에이전트</h3><p>시장에서 선수를 선택해 계약을 제안하고, 에이전트 메뉴에서 합의나 역제안에 서명하세요. 소속 선수는 재계약과 매각이 가능합니다. 다음 시즌 전 계약 잔여 1년인 선수를 확인하세요.</p><h3>코치 · 가상 신인</h3><p>5개 분야의 가상 코치를 선임할 수 있습니다. 시즌을 넘기면 나이와 계약 기간이 변하고 가상 신인이 입단합니다. 실명 선수와 가상 선수는 배지로 구분합니다.</p><h3>리그와 게임 규칙</h3><p>13개 리그의 구단으로 플레이할 수 있습니다. 단축 모드는 홈·원정 2회전이며, 정규 길이는 리그의 경기 수를 참고합니다. 일정은 게임이 생성합니다. 모든 리그에 통합 순위와 상위 4팀 플레이오프(준결승 3전 2선승, 결승 5전 3선승)를 적용합니다. 실제 지구별 진출·전후기·포스팅·외국인 제한·마이너리그·국제대회 규정은 아직 적용하지 않았습니다.</p><h3>선수 데이터</h3><p>{rosterNote} MLB·NPB는 공개 등록 명단, KBO와 기타 리그는 확인된 실명 선수 일부를 반영했습니다. 겨울 리그는 2025–26 구성 기준입니다. 정보 확인일: 2026-09-07.</p><p>에이전트·코치는 가상 인물입니다. 실제 인물이나 소속사의 계약 조건을 재현하지 않습니다. 선수 이적은 국가별 법적 절차를 생략한 게임 규칙으로 처리합니다.</p><div className="source-links"><a href="https://www.koreabaseball.com/Record/Player/HitterBasic/Basic1.aspx" target="_blank" rel="noreferrer">KBO 선수 기록 ↗</a><a href="https://www.mlb.com/dodgers/roster" target="_blank" rel="noreferrer">MLB 공개 로스터 ↗</a><a href="https://npb.jp/bis/eng/teams/rst_g.html" target="_blank" rel="noreferrer">NPB 등록 명단 ↗</a></div></div></DialogContent></Dialog>}

type CareerData={state:GameState|null;revision:number;ledger:FinanceEntry[]};
export default function Game(){
 const [data,setData]=useState<{world:WorldCatalog;career:CareerData}|null>(null),[error,setError]=useState(''),[attempt,setAttempt]=useState(0);
 useEffect(()=>{const abort=new AbortController();setError('');Promise.all(['/api/catalog','/api/career'].map(async url=>{const response=await fetch(url,{cache:'no-store',signal:abort.signal});const body=await response.json();if(!response.ok)throw new Error(body.error||'데이터를 불러오지 못했습니다.');return body;})).then(([world,career])=>setData({world,career})).catch(e=>{if(!abort.signal.aborted)setError(e.message||'연결하지 못했습니다.');});return()=>abort.abort();},[attempt]);
 if(!data)return <main className="catalog-loading"><div className="brand"><Baseball/><span>DUGOUT<i>WORLD BASEBALL MANAGER</i></span></div>{error?<><h1>커리어를 불러오지 못했습니다</h1><p>{error}</p><button className="button primary" onClick={()=>setAttempt(n=>n+1)}>다시 연결</button></>:<><LoaderCircle size={32} className="spin"/><h1>커리어 불러오는 중</h1><p>리그, 선수단, 저장된 커리어를 불러오는 중입니다.</p></>}</main>;
 return <WorldProvider world={data.world}><GameScreen initial={data.career}/></WorldProvider>;
}
